/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let attempt_limit = config.attempt_limit();
    let mut attempt = 1;

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= attempt_limit => {
